:root {
  --bg: #1a1a2e;
  --card-bg: #16213e;
  --text: #e0e0e0;
  --accent: #e94560;
  --accent-hover: #ff6b81;
  --border: #2a2a4a;
  --focus: #ffd166;
  --swatch-radius: 8px;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--bg);
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  color: var(--text);
  padding: 16px;
}

.card {
  background: var(--card-bg);
  border-radius: 16px;
  padding: 32px 24px;
  max-width: 600px;
  width: 100%;
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.4);
  text-align: center;
}

h1 {
  font-size: 1.75rem;
  font-weight: 700;
  margin-bottom: 8px;
  letter-spacing: 0.02em;
}

.subtitle {
  font-size: 1rem;
  color: #a0a0b0;
  margin-bottom: 28px;
  line-height: 1.5;
}

.palette {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
  justify-content: center;
  margin-bottom: 28px;
}

.swatch {
  flex: 1 1 0;
  min-width: 90px;
  max-width: 110px;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 6px;
}

.swatch-color {
  width: 100%;
  aspect-ratio: 1 / 1;
  border-radius: var(--swatch-radius);
  border: 2px solid var(--border);
  transition: transform 0.15s ease, border-color 0.15s ease;
}

.swatch-color:hover {
  transform: scale(1.05);
  border-color: #555;
}

.hex {
  font-family: 'Courier New', monospace;
  font-size: 0.85rem;
  font-weight: 600;
  letter-spacing: 0.05em;
  text-transform: uppercase;
  user-select: all;
}

.lock-btn {
  background: transparent;
  border: 2px solid var(--border);
  border-radius: 6px;
  color: var(--text);
  font-size: 0.8rem;
  padding: 4px 10px;
  cursor: pointer;
  transition: all 0.15s ease;
  font-family: inherit;
  line-height: 1.4;
  min-height: 32px;
}

.lock-btn:hover {
  border-color: var(--accent);
  color: var(--accent-hover);
}

.lock-btn:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
}

.lock-btn[aria-pressed="true"] {
  background: var(--accent);
  border-color: var(--accent);
  color: #fff;
}

.lock-btn[aria-pressed="true"]:hover {
  background: var(--accent-hover);
  border-color: var(--accent-hover);
}

.generate-btn {
  background: var(--accent);
  color: #fff;
  border: none;
  border-radius: 10px;
  padding: 14px 28px;
  font-size: 1.1rem;
  font-weight: 600;
  font-family: inherit;
  cursor: pointer;
  transition: background 0.15s ease, transform 0.1s ease;
  min-height: 48px;
  width: 100%;
}

.generate-btn:hover {
  background: var(--accent-hover);
}

.generate-btn:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
}

.generate-btn:active {
  transform: scale(0.97);
}

@media (max-width: 480px) {
  .card {
    padding: 24px 16px;
  }
  .swatch {
    min-width: 70px;
  }
  .hex {
    font-size: 0.75rem;
  }
  .lock-btn {
    font-size: 0.7rem;
    padding: 3px 6px;
    min-height: 28px;
  }
}

const paletteEl = document.getElementById('palette');
const generateBtn = document.getElementById('generateBtn');

const NUM_SWATCHES = 5;
const locked = new Array(NUM_SWATCHES).fill(false);
let colors = [];

function hslToHex(h, s, l) {
  s /= 100;
  l /= 100;
  const a = s * Math.min(l, 1 - l);
  const f = n => {
    const k = (n + h / 30) % 12;
    const color = l - a * Math.max(Math.min(k - 3, 9 - k, 1), -1);
    return Math.round(255 * color).toString(16).padStart(2, '0');
  };
  return `#${f(0)}${f(8)}${f(4)}`;
}

function generateHarmonious() {
  const baseHue = Math.random() * 360;
  const scheme = Math.floor(Math.random() * 3);
  const hues = [];

  for (let i = 0; i < NUM_SWATCHES; i++) {
    let h;
    if (scheme === 0) {
      h = (baseHue + i * 30) % 360;
    } else if (scheme === 1) {
      h = (baseHue + (i % 2 === 0 ? 0 : 180) + i * 15) % 360;
    } else {
      h = (baseHue + i * 72) % 360;
    }
    const s = 55 + Math.random() * 25;
    const l = 45 + Math.random() * 20;
    hues.push(hslToHex(h, s, l));
  }
  return hues;
}

function render() {
  paletteEl.innerHTML = '';
  colors.forEach((hex, i) => {
    const wrap = document.createElement('div');
    wrap.className = 'swatch';

    const colorBox = document.createElement('div');
    colorBox.className = 'swatch-color';
    colorBox.style.backgroundColor = hex;

    const hexLabel = document.createElement('span');
    hexLabel.className = 'hex';
    hexLabel.textContent = hex;

    const lockBtn = document.createElement('button');
    lockBtn.className = 'lock-btn';
    lockBtn.type = 'button';
    lockBtn.setAttribute('aria-pressed', locked[i]);
    lockBtn.setAttribute('aria-label', `Lock color ${hex}`);
    lockBtn.textContent = locked[i] ? 'Locked' : 'Lock';
    lockBtn.addEventListener('click', () => {
      locked[i] = !locked[i];
      render();
    });

    wrap.append(colorBox, hexLabel, lockBtn);
    paletteEl.appendChild(wrap);
  });
}

function generate() {
  const newColors = generateHarmonious();
  for (let i = 0; i < NUM_SWATCHES; i++) {
    if (!locked[i]) colors[i] = newColors[i];
  }
  render();
}

generateBtn.addEventListener('click', generate);

colors = generateHarmonious();
render();
